{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Pub/Sub topic is not encrypted with a customer-managed key",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The topic does not set kms_key_name, so it relies on Google-managed encryption rather than a customer-controlled Cloud KMS key as required by the applicable policy."
    }
  ],
  "patched_code": "variable \"pubsub_kms_key_name\" {\n  description = \"Fully qualified Cloud KMS CryptoKey name used to encrypt the Pub/Sub topic.\"\n  type        = string\n}\n\nresource \"google_pubsub_topic\" \"notification_trigger\" {\n  name         = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n  kms_key_name = var.pubsub_kms_key_name\n}\n",
  "fix_summary": "Configured the Pub/Sub topic to use a caller-supplied Cloud KMS key and added a required variable for the fully qualified key name."
}
